package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();ids:=[]int64{335,348,349,350,377,379,380,381,382,383,384,402,403,404,408,410,411,412,414,432,433,434,435,436,442};rows,e:=p.Query(c,`select r.id,r.status,r.capture_via,r.source_kind,coalesce(r.preferred_relay_group_id,0),coalesce(a.execution_class,''),coalesce(a.server_id,''),r.cron_timezone,r.daily_window_start::text,r.daily_window_end::text,r.clip_duration_sec,r.start_at,r.end_at from recordings r left join recording_assignments a on a.stream_id=r.stream_id where r.account_id=47 and r.id=any($1::bigint[]) order by r.id`,ids);if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var id,grp,clip int64;var st,via,sk,ec,server,tz,ds,de string;var start,end any;if e:=rows.Scan(&id,&st,&via,&sk,&grp,&ec,&server,&tz,&ds,&de,&clip,&start,&end);e!=nil{panic(e)};fmt.Printf("META %d status=%s via=%s source=%s relay_group=%d class=%s server=%s tz=%s window=%s-%s clip=%d start=%v end=%v\n",id,st,via,sk,grp,ec,server,tz,ds,de,clip,start,end)}}
